import leetcode.medium.OnlineStockSpan;
import org.junit.Test;
import static org.junit.Assert.*;

public class OnlineStockSpanTest {

    @Test
    public void nextPriceLessThanPreviousPriceTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.next(100);
        int result = stockSpan.next(80);
        assertEquals(1, result);
    }

    @Test
    public void nextPriceGreaterThanPreviousPriceTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.next(100);
        int result = stockSpan.next(120);
        assertEquals(2, result);
    }

    @Test
    public void calculateSpansPricesDecreasingTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] prices = new int[]{100, 80, 60, 40};
        int[] result = stockSpan.calculateSpans(prices);
        assertArrayEquals(new int[]{1, 1, 1, 1}, result);
    }

    @Test
    public void calculateSpansPricesIncreasingTest() {
       OnlineStockSpan stockSpan = new OnlineStockSpan();
       int[] prices = new int[]{10, 20, 30, 40};
       int[] result = stockSpan.calculateSpans(prices);
       assertArrayEquals(new int[]{1, 2, 3, 4}, result);
    }

    @Test
    public void calculateSpansPriceUnchangedTest() {
       OnlineStockSpan stockSpan = new OnlineStockSpan();
       int[] prices = new int[]{50, 50, 50, 50};
       int[] result = stockSpan.calculateSpans(prices);
       assertArrayEquals(new int[]{1, 2, 3, 4}, result);
    }
}
